// ============================================================
// NODE: Code in JavaScript  (VERSION MISE À JOUR)
// Regroupe les 34 lignes (17 agences x 2 types de crédit),
// calcule la probabilité moyenne d'atteinte de l'objectif par
// agence, détermine la catégorie (En bonne voie / A risque /
// En danger), identifie la meilleure et la moins bonne agence,
// et prépare un prompt où le LLM ne génère QUE les 3 lignes de
// recommandations.
//
// Changements vs version précédente :
// - Aucun changement de logique de calcul (seuils, moyennes,
//   tri) : c'était déjà correct et vérifié contre les données.
// - Renommage interne "confiance" -> reste "confiance" en code
//   (pour ne rien casser en aval) mais le prompt LLM et les
//   commentaires utilisent désormais le terme métier
//   "probabilité d'atteinte de l'objectif".
// - "details" par agence garanti trié Consommation puis
//   Immobilier, pour un affichage de tableau prévisible dans
//   le Code node 2.
// ============================================================

const items = $input.all();

if (!items || items.length === 0) {
  throw new Error('Aucune donnée reçue en entrée (items vide).');
}

const CREDIT_MAP = { 0: 'Consommation', 1: 'Immobilier' };
const CREDIT_ORDER = ['Consommation', 'Immobilier']; // ordre d'affichage garanti

// Seuils de classement (modifiables ici uniquement)
const SEUIL_BONNE_VOIE = 70; // probabilité moyenne >= 70          -> "En bonne voie"
const SEUIL_RISQUE     = 40; // 40 <= probabilité moyenne < 70     -> "A risque"
                              // probabilité moyenne < 40           -> "En danger"

// --- 1. Regrouper les lignes par agence ---
const agenceGroups = {};

items.forEach((item, idx) => {
  const data = item.json || {};

  if (!('AGENCE' in data)) {
    throw new Error(`Ligne ${idx} : champ "AGENCE" manquant.`);
  }

  const agenceRaw = data['AGENCE'];
  let agenceIndex; // index brut (0-based), utilisé pour trier
  let agenceNum;   // numéro affiché dans le rapport (1-based)

  if (typeof agenceRaw === 'string' && /AGENCE/i.test(agenceRaw)) {
    // Format déjà "AGENCE 1", "Agence 5", etc. -> on extrait le numéro tel quel,
    // pas d'ajout de +1 car il est déjà au format d'affichage.
    const match = agenceRaw.match(/(\d+)/);
    if (!match) {
      throw new Error(`Ligne ${idx} : AGENCE="${agenceRaw}" ne contient aucun numéro.`);
    }
    agenceNum = parseInt(match[1], 10);
    agenceIndex = agenceNum - 1;
  } else {
    // Format brut : nombre (0, 1, 2...) -> on ajoute 1 pour l'affichage.
    agenceIndex = parseInt(agenceRaw, 10);
    if (isNaN(agenceIndex)) {
      throw new Error(`Ligne ${idx} : AGENCE="${agenceRaw}" n'est pas un nombre valide.`);
    }
    agenceNum = agenceIndex + 1; // index+1 : AGENCE 0 (fichier) -> "AGENCE 1" (rapport)
  }

  const agenceLabel = `AGENCE ${agenceNum}`;

  const creditTypeRaw = parseInt(data['Credit_Type'], 10);
  const creditLabel = CREDIT_MAP[creditTypeRaw] !== undefined ? CREDIT_MAP[creditTypeRaw] : 'Inconnu';

  // Le nom de cette colonne a varié selon les exports H2O :
  // ancien format : "P (Hit_Objective=1)Probability"
  // nouveau format : "P (Hit_Objective=Yes)Probability"
  const probaRaw = parseFloat(
    data['P (Hit_Objective=Yes)Probability'] ??
    data['P (Hit_Objective=1)Probability']
  );
  const confiance = isNaN(probaRaw) ? 0 : Math.round(probaRaw * 1000) / 10; // en %, 1 décimale

  // "Statut_Predit" n'existe pas dans tous les exports : on le reconstruit
  // à partir de "Prediction (Hit_Objective)" si besoin ('Yes'/'No' ou '1'/'0').
  const predictionRaw = String(data['Prediction (Hit_Objective)'] ?? '').trim();
  let statut = data['Statut_Predit'];
  if (!statut) {
    if (predictionRaw === 'Yes' || predictionRaw === '1') statut = '🟢 On Track';
    else if (predictionRaw === 'No' || predictionRaw === '0') statut = '🔴 Will Miss';
    else statut = 'Inconnu';
  }

  const objectifRaw = parseInt(data['OBJECTIF_Mensuel'], 10);
  const objectif = isNaN(objectifRaw) ? 0 : objectifRaw;

  if (!agenceGroups[agenceLabel]) {
    agenceGroups[agenceLabel] = { agence: agenceLabel, agenceIndex, details: [] };
  }

  agenceGroups[agenceLabel].details.push({ credit_type: creditLabel, confiance, statut, objectif });
});

// --- 2. Calculer la probabilité moyenne et la catégorie par agence ---
function determinerCategorie(confianceMoyenne) {
  if (confianceMoyenne >= SEUIL_BONNE_VOIE) return 'En bonne voie';
  if (confianceMoyenne >= SEUIL_RISQUE) return 'A risque';
  return 'En danger';
}

const agences = Object.values(agenceGroups)
  .sort((a, b) => a.agenceIndex - b.agenceIndex) // ordre stable : AGENCE 1, 2, 3...
  .map(g => {
    // Trier les détails dans un ordre d'affichage fixe (Consommation puis Immobilier)
    const detailsTries = [...g.details].sort(
      (a, b) => CREDIT_ORDER.indexOf(a.credit_type) - CREDIT_ORDER.indexOf(b.credit_type)
    );
    const total = g.details.reduce((sum, d) => sum + d.confiance, 0);
    const confianceMoyenne = Math.round((total / g.details.length) * 10) / 10;
    return {
      agence: g.agence,
      confiance_moyenne: confianceMoyenne,
      categorie: determinerCategorie(confianceMoyenne),
      details: detailsTries
    };
  });

if (agences.length === 0) {
  throw new Error('Aucune agence trouvée après regroupement.');
}

// --- 3. Compter les catégories ---
const onTrack  = agences.filter(a => a.categorie === 'En bonne voie');
const atRisk   = agences.filter(a => a.categorie === 'A risque');
const enDanger = agences.filter(a => a.categorie === 'En danger');

// --- 4. Meilleure et moins bonne agence ---
const sortedByConfiance = [...agences].sort((a, b) => b.confiance_moyenne - a.confiance_moyenne);
const best = sortedByConfiance[0];
const worst = sortedByConfiance[sortedByConfiance.length - 1];

// --- 5. Bloc de données lisible (utile pour debug/inspection) ---
const dataBlock =
`- Agences en bonne voie : ${onTrack.length}
- Agences à risque : ${atRisk.length}
- Agences en danger : ${enDanger.length}
- Meilleure agence : ${best.agence} (probabilité d'atteinte objectif : ${best.confiance_moyenne}%)
- Agence à surveiller : ${worst.agence} (probabilité d'atteinte objectif : ${worst.confiance_moyenne}%)`;

// --- 6. Prompt envoyé au LLM : UNIQUEMENT les 3 recommandations ---
// Le LLM ne voit jamais les chiffres globaux, le tableau complet, ni le
// format du rapport : il ne peut donc ni les modifier ni les halluciner.
const prompt =
`Tu es un assistant qui rédige UNIQUEMENT 3 lignes de recommandations pour un rapport bancaire interne. Tu ne fais rien d'autre.

Contexte (ne pas le répéter dans ta réponse) :
- Meilleure agence : ${best.agence}, probabilité d'atteinte de l'objectif ${best.confiance_moyenne}%
- Agence à surveiller en priorité : ${worst.agence}, probabilité d'atteinte de l'objectif ${worst.confiance_moyenne}%

Consignes strictes, à respecter absolument :
1. Réponds UNIQUEMENT avec exactement 3 lignes, chacune commençant par "- ".
2. N'écris RIEN avant ou après ces 3 lignes : pas de titre, pas d'introduction, pas de conclusion, pas d'explication, pas de markdown.
3. N'utilise QUE ces deux noms d'agence, aucun autre nom, aucune autre banque : "${best.agence}" et "${worst.agence}".
4. Ligne 1 : une recommandation concrète pour améliorer la situation de ${worst.agence}.
5. Ligne 2 : une deuxième recommandation concrète et différente de la ligne 1, pour ${worst.agence}.
6. Ligne 3 : une recommandation pour maintenir le bon niveau de ${best.agence}.
7. Chaque ligne = une seule phrase claire et professionnelle, en français.

Réponds maintenant avec uniquement les 3 lignes :`;

// --- 7. Sortie ---
return [{
  json: {
    total_agences: agences.length,
    total_on_track: onTrack.length,
    total_at_risk: atRisk.length,
    total_en_danger: enDanger.length,
    best_agence: best.agence,
    best_confiance: best.confiance_moyenne,
    worst_agence: worst.agence,
    worst_confiance: worst.confiance_moyenne,
    data_block: dataBlock,
    prompt: prompt,
    agences: agences
  }
}];

// ============================================================
// NODE: Code in JavaScript1  (VERSION FINALE)
// Récupère les recommandations du LLM et les données fiables
// du Code 1, reconstruit le rapport complet en HTML.
//
// Reproduit EXACTEMENT la maquette validée :
// - Tableau des 17 agences (toutes catégories), trié de la
//   moins bonne à la meilleure.
// - AGENCE la mieux classée mise en valeur en doré avec 🏆.
// - "Probabilité d'atteinte de l'objectif" partout au lieu de
//   "Confiance".
// - Légende / note de bas de page avec les seuils.
// - Pas de ligne "dashboard Power BI" (envoyé séparément).
// ============================================================

// --- 1. Récupérer les données fiables de Code 1 ---
let baseData = null;
const possibleNames = ['Code in JavaScript', 'Code', 'Code1', 'Code in JavaScript1'];

for (const name of possibleNames) {
  try {
    const node = $(name);
    if (node && node.first()) {
      baseData = node.first().json;
      break;
    }
  } catch (e) {
    continue;
  }
}

if (!baseData) {
  baseData = $input.first().json;
}

const needed = ['total_on_track', 'total_at_risk', 'total_en_danger',
                 'best_agence', 'best_confiance', 'worst_agence', 'worst_confiance', 'agences'];

for (const key of needed) {
  if (baseData[key] === undefined) {
    throw new Error(`Champ manquant dans Code 1 : "${key}". Champs disponibles : ${Object.keys(baseData).join(', ')}`);
  }
}

// --- 2. Récupérer le texte brut du LLM ---
const llmInput = $input.first().json;
const rawText =
  llmInput.text ??
  llmInput.response ??
  llmInput.output ??
  llmInput.content ??
  '';

// --- 3. Extraire les 3 lignes de recommandations ---
const candidateLines = rawText
  .split('\n')
  .map(l => l.trim())
  .filter(l => l.startsWith('-') || l.startsWith('•'))
  .map(l => l.replace(/^[-•]\s*/, '').trim())
  .filter(l => l.length > 10);

const bestLower = baseData.best_agence.toLowerCase();
const worstLower = baseData.worst_agence.toLowerCase();

const validLines = candidateLines.filter(line => {
  const lower = line.toLowerCase();
  return lower.includes(bestLower) || lower.includes(worstLower);
});

const fallbacks = [
  `Organiser un suivi rapproché avec l'équipe de ${baseData.worst_agence} pour identifier les blocages et améliorer la probabilité d'atteinte de l'objectif.`,
  `Mettre en place un plan d'action à court terme pour ${baseData.worst_agence} avec des indicateurs hebdomadaires.`,
  `Capitaliser sur les bonnes pratiques de ${baseData.best_agence} et les partager avec les autres agences.`
];

const recs = [];
for (let i = 0; i < 3; i++) {
  recs.push(validLines[i] || fallbacks[i]);
}

// --- 4. Construire le tableau complet des 17 agences ---
// Trié de la probabilité la plus faible à la plus forte.
const agencesTriees = [...baseData.agences].sort((a, b) => a.confiance_moyenne - b.confiance_moyenne);

function detailParType(details, typeLabel) {
  const d = details.find(x => x.credit_type === typeLabel);
  return d ? `${d.confiance}%` : '—';
}

function badgeCategorie(cat) {
  if (cat === 'En danger') return '<span style="color:#CC0000;font-weight:bold;">🔴 Danger</span>';
  if (cat === 'A risque') return '<span style="color:#B8860B;font-weight:bold;">🟡 À risque</span>';
  return '<span style="color:#006400;font-weight:bold;">🟢 Bonne voie</span>';
}

const tableRows = agencesTriees.map((a, idx) => {
  const bg = idx % 2 === 0 ? '#ffffff' : '#f7f7f7';
  const conso = detailParType(a.details, 'Consommation');
  const immo = detailParType(a.details, 'Immobilier');
  const isBest = a.agence === baseData.best_agence;
  const nameStyle = isBest
    ? 'font-weight:bold;border-bottom:1px solid #eee;color:#B8860B;'
    : 'font-weight:bold;border-bottom:1px solid #eee;';
  const nameLabel = isBest ? `${a.agence} 🏆` : a.agence;

  return `<tr style="background-color:${bg};">
    <td style="padding:8px 10px;${nameStyle}">${nameLabel}</td>
    <td style="padding:8px 10px;border-bottom:1px solid #eee;text-align:center;">${a.confiance_moyenne}%</td>
    <td style="padding:8px 10px;border-bottom:1px solid #eee;text-align:center;">${conso}</td>
    <td style="padding:8px 10px;border-bottom:1px solid #eee;text-align:center;">${immo}</td>
    <td style="padding:8px 10px;border-bottom:1px solid #eee;text-align:center;">${badgeCategorie(a.categorie)}</td>
  </tr>`;
}).join('\n');

const tableAgencesHtml = `
<p style="font-size:16px;font-weight:bold;color:#003366;margin-top:20px;margin-bottom:8px;">📊 Détail par Agence (${agencesTriees.length} agences)</p>
<table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:10px;">
  <thead>
    <tr style="background-color:#003366;color:white;">
      <th style="padding:8px 10px;text-align:left;">Agence</th>
      <th style="padding:8px 10px;">Probabilité d'atteinte objectif</th>
      <th style="padding:8px 10px;">Consommation</th>
      <th style="padding:8px 10px;">Immobilier</th>
      <th style="padding:8px 10px;">Statut</th>
    </tr>
  </thead>
  <tbody>
    ${tableRows}
  </tbody>
</table>`;

// --- 5. Légende / note de bas de page ---
const legendeHtml = `
<p style="font-size:12px;color:#777;margin-top:20px;padding-top:10px;border-top:1px dashed #ddd;">
  <strong>Légende :</strong>
  🟢 En bonne voie (≥ 70%) &nbsp;|&nbsp;
  🟡 À risque (40% – 69%) &nbsp;|&nbsp;
  🔴 En danger (&lt; 40%)<br>
  <em>La "Probabilité d'atteinte de l'objectif" est calculée par le modèle prédictif à partir des indicateurs de pipe et de réalisations partielles, moyennée sur les crédits Consommation et Immobilier.</em>
</p>`;

// --- 6. Construire le texte brut (fallback / logs) ---
const reportText =
`Bonjour Directeur Régional,

Voici le résumé des performances commerciales de cette semaine :

🟢 Situation Globale
- Agences en bonne voie : ${baseData.total_on_track}
- Agences à risque : ${baseData.total_at_risk}
- Agences en danger : ${baseData.total_en_danger}

🏆 Top Performer
- ${baseData.best_agence} — Probabilité d'atteinte objectif : ${baseData.best_confiance}%

⚠️ À Surveiller en Priorité
- ${baseData.worst_agence} — Probabilité d'atteinte objectif : ${baseData.worst_confiance}%

📋 Recommandations
- ${recs[0]}
- ${recs[1]}
- ${recs[2]}

Cordialement,
Système d'Alertes BCP`;

// --- 7. Construire le HTML final ---
const fullHtml = `<!DOCTYPE html>
<html>
<body style="font-family:Arial,sans-serif;font-size:15px;line-height:1.8;color:#222;max-width:650px;margin:40px auto;padding:0;border:1px solid #e0e0e0;border-radius:8px;">
<div style="background-color:#003366;color:white;padding:15px 20px;border-radius:6px 6px 0 0;margin-bottom:20px;">
  <h2 style="margin:0;font-size:18px;">📊 Rapport Hebdomadaire — Banque Populaire Béni Mellal</h2>
</div>
<div style="padding:0 25px 25px 25px;">

<p style="margin:6px 0;">Bonjour Directeur Régional,</p>
<p style="margin:6px 0;">Voici le résumé des performances commerciales de cette semaine :</p>

<p style="font-size:16px;font-weight:bold;color:#006400;margin-top:20px;margin-bottom:5px;">🟢 Situation Globale</p>
<p style="margin:4px 0;padding-left:20px;">• Agences en bonne voie : ${baseData.total_on_track}</p>
<p style="margin:4px 0;padding-left:20px;">• Agences à risque : ${baseData.total_at_risk}</p>
<p style="margin:4px 0;padding-left:20px;">• Agences en danger : ${baseData.total_en_danger}</p>

<p style="font-size:16px;font-weight:bold;color:#B8860B;margin-top:20px;margin-bottom:5px;">🏆 Top Performer</p>
<p style="margin:4px 0;padding-left:20px;">• ${baseData.best_agence} — Probabilité d'atteinte objectif : ${baseData.best_confiance}%</p>

<p style="font-size:16px;font-weight:bold;color:#CC0000;margin-top:20px;margin-bottom:5px;">⚠️ À Surveiller en Priorité</p>
<p style="margin:4px 0;padding-left:20px;">• ${baseData.worst_agence} — Probabilité d'atteinte objectif : ${baseData.worst_confiance}%</p>

${tableAgencesHtml}

<p style="font-size:16px;font-weight:bold;color:#003366;margin-top:20px;margin-bottom:5px;">📋 Recommandations</p>
<p style="margin:4px 0;padding-left:20px;">• ${recs[0]}</p>
<p style="margin:4px 0;padding-left:20px;">• ${recs[1]}</p>
<p style="margin:4px 0;padding-left:20px;">• ${recs[2]}</p>

${legendeHtml}

<p style="margin:14px 0 4px 0;color:#666;">Cordialement,</p>
<p style="margin:0;color:#666;">Système d'Alertes BCP</p>

</div>
<div style="margin-top:10px;padding:15px 25px;border-top:1px solid #e0e0e0;font-size:12px;color:#999;border-radius:0 0 6px 6px;background-color:#f9f9f9;">
  Ce rapport est généré automatiquement par le Système d'Alertes IA — BCP Région Béni Mellal
</div>
</body>
</html>`;

// --- 8. Retourner ---
return [{
  json: {
    rapport_texte: reportText,
    rapport_full_html: fullHtml,
    recommandations_source: validLines.length >= 3 ? 'LLM' : 'fallback',
    nb_agences_table: agencesTriees.length
  }
}];
